   190	// extractFilesFromApplyPatch returns every file path in an apply_patch envelope,
   191	// across Add/Update/Delete entries, deduplicated.
   192	func extractFilesFromApplyPatch(input string) []string {
   193		added, modified, deleted := classifyApplyPatchPaths(input)
   194		total := len(added) + len(modified) + len(deleted)
   195		if total == 0 {
   196			return nil
   197		}
   198		files := make([]string, 0, total)
   199		files = append(files, added...)
   200		files = append(files, modified...)
   201		files = append(files, deleted...)
   202		return files
   203	}
