   205	// classifyApplyPatchPaths splits an apply_patch envelope into added, modified,
   206	// and deleted file paths. The grammar (codex-rs/apply-patch/src/parser.rs)
   207	// supports renames via "*** Update File: old\n*** Move to: new", which we
   208	// reclassify as a Delete on the source path and an Add on the destination.
   209	// Add and Delete are sticky — subsequent Updates on the same path don't
   210	// downgrade them. Each bucket is sorted for deterministic output.
   211	func classifyApplyPatchPaths(input string) (added, modified, deleted []string) {
   212		bucket := make(map[string]string)
   213		var lastUpdate string
   214		for _, line := range strings.Split(input, "\n") {
   215			if m := applyPatchFileRegex.FindStringSubmatch(line); m != nil {
   216				verb := m[1]
   217				path := strings.TrimSpace(m[2])
   218				if path == "" {
   219					continue
   220				}
   221				if verb == applyPatchVerbUpdate {
   222					lastUpdate = path
   223				} else {
   224					lastUpdate = ""
   225				}
   226				if existing, ok := bucket[path]; ok {
   227					if existing == applyPatchVerbAdd || existing == applyPatchVerbDelete {
   228						continue
   229					}
   230				}
   231				bucket[path] = verb
   232				continue
   233			}
   234			if m := applyPatchMoveRegex.FindStringSubmatch(line); m != nil {
   235				target := strings.TrimSpace(m[1])
   236				if target == "" {
   237					continue
   238				}
   239				if lastUpdate != "" {
   240					if existing, ok := bucket[lastUpdate]; !ok || (existing != applyPatchVerbAdd && existing != applyPatchVerbDelete) {
   241						bucket[lastUpdate] = applyPatchVerbDelete
   242					}
   243				}
   244				if existing, ok := bucket[target]; !ok || (existing != applyPatchVerbAdd && existing != applyPatchVerbDelete) {
   245					bucket[target] = applyPatchVerbAdd
   246				}
   247				lastUpdate = ""
   248			}
   249		}
   250		for path, verb := range bucket {
   251			switch verb {
   252			case applyPatchVerbAdd:
   253				added = append(added, path)
   254			case applyPatchVerbUpdate:
   255				modified = append(modified, path)
   256			case applyPatchVerbDelete:
   257				deleted = append(deleted, path)
   258			}
   259		}
   260		sort.Strings(added)
   261		sort.Strings(modified)
   262		sort.Strings(deleted)
   263		return added, modified, deleted
   264	}
